const fs = require('fs');

function fun(x, a, b, c, countObj) {
    if (a !== x || b !== x || c !== x) {
        if (c !== x) {
            if (a + b > x) {
                c = x;
            } else {
                c = b + a - 1;
            }
            countObj.count++;
        }
        fun(x, c, a, b, countObj);
    }
}

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
    const x = input[0];
    const y = input[1];
    const countObj = { count: 0 };
    fun(x, y, y, y, countObj);
    console.log(countObj.count);
}

main();

